import React, { useState } from 'react';

const Donation = () => {
  const [selectedQR, setSelectedQR] = useState(null);


  const donationTiers = [
    { id: 1, amount: '$2000 - 1 U$S', qrImage: 'data:image/jpeg;base64,', label: 'Donación Feliz' },
    { id: 2, amount: '$4000 - 2 U$S', qrImage: 'data:image/jpeg;base64,', label: 'Donación Muy Feliz' },
    { id: 3, amount: '$8000 - 4 U$S', qrImage: 'data:image/jpeg;base64,', label: 'Donación Extra Feliz' },
  ];

  return (
    
    <div className="max-w-4xl mx-auto p-6 bg-white rounded-2xl shadow-lg border border-gray-100">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold text-gray-800 mb-2">Apoya nuestro proyecto</h2>
        <p className="text-gray-600">MercadoPago - Escanea el código QR según el monto que desees aportar </p>
      </div>

      {/* Grid de QRs por monto */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
        {donationTiers.map((tier) => (
          <div
            key={tier.id}
            className="flex flex-col items-center p-5 rounded-xl border border-gray-200 bg-gray-50 hover:shadow-md transition-shadow"
          >
            <span className="text-2xl font-black text-emerald-600 mb-1">{tier.amount}</span>
            <span className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-4">
              {tier.label}
            </span>

            {/* Contenedor de la imagen QR */}
            <div className="relative group cursor-pointer" onClick={() => setSelectedQR(tier.qrImage)}>
              <img
                src={tier.qrImage}
                alt={`QR Donación ${tier.amount}`}
                className="w-48 h-48 object-cover rounded-lg border bg-white p-2 shadow-sm"
              />
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity rounded-lg flex items-center justify-center text-white text-xs font-medium">
                Ampliar QR
              </div>
            </div>

            <p className="text-xs  mt-3 text-center">Toca para Ampliar - MercadoPago </p>
          </div>
        ))}
      </div>

      {/* Separador */}
      <div className="relative my-8">
        <div className="absolute inset-0 flex items-center">
          <div className="w-full border-t border-gray-200"></div>
        </div>
        <div className="relative flex justify-center text-sm">
          <span className="px-4 bg-white text-gray-500 font-medium">Invitame un CAFECITO</span>
        </div>
      </div>

      <div className="items-center"  >

        <a
          href="https://cafecito.app/sirfreedom"
          target="_blank"
          rel="noopener noreferrer"
          aria-label="Invitame un café en cafecito.app"
        >
          <img
            src="https://cdn.cafecito.app/imgs/buttons/button_3.png"
            srcSet="https://cdn.cafecito.app/imgs/buttons/button_3.png 1x, https://cdn.cafecito.app/imgs/buttons/button_3_2x.png 2x, https://cdn.cafecito.app/imgs/buttons/button_3_3.75x.png 3.75x"
            alt="Invitame un café en cafecito.app"
            loading="lazy"
          />
        </a>

      </div>

      {/* Modal simple para ampliar la imagen del QR al hacer click */}
      {selectedQR && (
        <div
          className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4"
          onClick={() => setSelectedQR(null)}
        >
          <div className="bg-white p-4 rounded-2xl max-w-sm w-full text-center relative" onClick={(e) => e.stopPropagation()}>
            <img src={selectedQR} alt="QR ampliado" className="w-full h-auto rounded-lg" />
            <button
              onClick={() => setSelectedQR(null)}
              className="mt-4 px-4 py-2 bg-gray-200 hover:bg-gray-300 text-gray-800 text-sm font-semibold rounded-lg w-full transition-colors"
            >
              Cerrar
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Donation;